import{_ as a,o as t,c as r,a3 as i}from"./chunks/framework.DQ-7HQaQ.js";const u=JSON.parse('{"title":"A research walkthrough","description":"Follow a fictional UFO collection from raw reports to reviewed knowledge and a cited answer.","frontmatter":{"title":"A research walkthrough","description":"Follow a fictional UFO collection from raw reports to reviewed knowledge and a cited answer."},"headers":[],"relativePath":"guide/walkthrough.md","filePath":"guide/walkthrough.md","lastUpdated":1794376220000}'),n={name:"guide/walkthrough.md"};function o(s,e,h,c,d,l){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="one-incident-several-accounts" tabindex="-1">One incident. Several accounts. <a class="header-anchor" href="#one-incident-several-accounts" aria-label="Permalink to &quot;One incident. Several accounts.&quot;">​</a></h1><p><strong>Fictional design example.</strong> This is not a real UFO finding or an implemented application demo.</p><h2 id="_1-import-three-reports" tabindex="-1">1. Import three reports <a class="header-anchor" href="#_1-import-three-reports" aria-label="Permalink to &quot;1. Import three reports&quot;">​</a></h2><p>A harbor witness describes a bright object. A second report repeats that account. A third describes a stationary light at roughly the same time. Two names may refer to the same incident; two people named Alex Lee may not be the same person.</p><p>Preserve each acquisition and source version. Identical bytes can share an artifact without erasing where each copy was obtained.</p><h2 id="_2-review-the-proposals" tabindex="-1">2. Review the proposals <a class="header-anchor" href="#_2-review-the-proposals" aria-label="Permalink to &quot;2. Review the proposals&quot;">​</a></h2><p>Extraction identifies mentions and proposes entities and claims. The reviewer sees surrounding passages and candidate matches.</p><p>Approve the incident alias only when context supports it. Keep the two people separate unless evidence establishes identity. Record the copied report&#39;s dependence. Preserve both movement descriptions instead of averaging them into a new story.</p><h2 id="_3-publish-a-revision" tabindex="-1">3. Publish a revision <a class="header-anchor" href="#_3-publish-a-revision" aria-label="Permalink to &quot;3. Publish a revision&quot;">​</a></h2><p>Review an immutable proposal against a known base revision. Publication validates identity assignments, evidence references, rights and permissions, then commits changes and their event together.</p><p>A later source or changed proposal requires a new review. No half-published result should survive a failed transaction.</p><h2 id="_4-ask-a-research-question" tabindex="-1">4. Ask a research question <a class="header-anchor" href="#_4-ask-a-research-question" aria-label="Permalink to &quot;4. Ask a research question&quot;">​</a></h2><blockquote><p>Which independent accounts describe movement, and where do their descriptions conflict?</p></blockquote><p>Chat retrieves authorized evidence from one published revision. Its answer streams with citations opening exact passages. The evidence panel identifies source dependence and unresolved assessments.</p><p>The answer explains what the reports support. It does not infer extraordinary physics merely from a witness&#39;s wording.</p><h2 id="_5-test-an-interruption" tabindex="-1">5. Test an interruption <a class="header-anchor" href="#_5-test-an-interruption" aria-label="Permalink to &quot;5. Test an interruption&quot;">​</a></h2><p>Stop a run or disconnect the browser. Committed partial text and the recorded outcome remain inspectable. Reconnection does not silently start another paid generation.</p><p>Reimport the same material: accepted records should not multiply. Correct a mistaken merge: the earlier decision should remain auditable.</p><h2 id="_6-move-the-library" tabindex="-1">6. Move the library <a class="header-anchor" href="#_6-move-the-library" aria-label="Permalink to &quot;6. Move the library&quot;">​</a></h2><p>Export the approved revision and open it on Linux without the Mac worker. Evidence remains readable. Missing capabilities are reported; unavailable semantic query encoding produces a clearly narrower search mode.</p><h2 id="what-students-should-explain" tabindex="-1">What students should explain <a class="header-anchor" href="#what-students-should-explain" aria-label="Permalink to &quot;What students should explain&quot;">​</a></h2><p>Where is identity decided? What makes an account independent? Which transaction owns publication? What survives a crash? What does a passing test fail to prove?</p><p>Use the <a href="./../project/acceptance">requirements</a> for acceptance criteria and the <a href="./../engineering/examples">executable labs</a> for runnable, narrower contracts.</p>',23)])])}const m=a(n,[["render",o]]);export{u as __pageData,m as default};
